CREATE TRIGGER local_speech_job_scope BEFORE INSERT ON local_speech_jobs WHEN NEW.state!='queued' OR NEW.attempts!=0 OR json_extract(NEW.intent,'$.job_id') IS NOT NEW.id OR json_extract(NEW.intent,'$.project_id') IS NOT NEW.project_id OR json_extract(NEW.intent,'$.chapter_id') IS NOT NEW.chapter_id OR json_extract(NEW.intent,'$.profile') IS NOT 'windows_sapi_pcm_v1' OR json_extract(NEW.intent,'$.external_fee_fen') IS NOT 0 OR NOT EXISTS(SELECT 1 FROM shot_plans p WHERE p.id=json_extract(NEW.intent,'$.plan_id') AND p.project_id=NEW.project_id AND p.content_hash=json_extract(NEW.intent,'$.plan_hash') AND json_extract(p.payload,'$.chapter_id')=NEW.chapter_id) OR NOT EXISTS(SELECT 1 FROM generation_tasks t WHERE t.id=NEW.task_id AND t.task_kind='local_speech' AND t.executor_type='local_speech_v1' AND json_extract(t.payload,'$.project_id')=NEW.project_id AND json_extract(t.payload,'$.chapter_id')=NEW.chapter_id AND json_extract(t.payload,'$.speech_job_id')=NEW.id) OR EXISTS(SELECT 1 FROM local_speech_jobs j WHERE j.id=NEW.id OR (j.project_id=NEW.project_id AND j.request_key=NEW.request_key)) BEGIN SELECT RAISE(ABORT,'Local speech original scope'); END
